package sqlite

func init() {
	for k, v := range ocrMediaExpectedSchemaSQL {
		expectedSchemaSQL[k] = v
	}
}

var ocrMediaExpectedSchemaSQL = map[string]string{
	"index:ix_media_assets_scope": "CREATE INDEX ix_media_assets_scope ON media_assets(owner_subject_id, scope_kind, scope_id, created_at)",
	"index:ix_media_operations_session": "CREATE INDEX ix_media_operations_session ON media_operations(media_session_id, created_at)",
	"index:ix_media_sessions_scope": "CREATE INDEX ix_media_sessions_scope ON media_sessions(owner_subject_id, scope_kind, scope_id, updated_at)",
	"index:ix_ocr_document_runs_scope": "CREATE INDEX ix_ocr_document_runs_scope ON ocr_document_runs(owner_subject_id, scope_kind, scope_id, created_at)",
	"index:ix_ocr_pack_notices_verified": "CREATE INDEX ix_ocr_pack_notices_verified ON ocr_pack_notices(verified_at DESC, manifest_digest ASC)",
	"index:ux_media_queue_current": "CREATE UNIQUE INDEX ux_media_queue_current ON media_queue_items(media_session_id) WHERE state = 'current'",
	"index:ux_ocr_pack_ops_active": "CREATE UNIQUE INDEX ux_ocr_pack_ops_active ON ocr_pack_operations(pack_id) WHERE phase NOT IN ('succeeded','failed','cancelled')",
	"table:media_assets": "CREATE TABLE media_assets (\n    asset_id TEXT PRIMARY KEY CHECK (length(asset_id) = 26 AND substr(asset_id, 1, 1) GLOB '[0-7]' AND asset_id NOT GLOB '*[^0123456789ABCDEFGHJKMNPQRSTVWXYZ]*'),\n    owner_subject_id TEXT NOT NULL CHECK (length(owner_subject_id) BETWEEN 1 AND 128),\n    scope_kind TEXT NOT NULL CHECK (scope_kind IN ('user','project')),\n    scope_id TEXT NOT NULL CHECK (length(scope_id) BETWEEN 1 AND 128),\n    source_kind TEXT NOT NULL CHECK (source_kind IN ('user_selected','artifact','workspace')),\n    source_ref TEXT NOT NULL CHECK (length(source_ref) BETWEEN 1 AND 1024),\n    file_identity TEXT NOT NULL CHECK (length(file_identity) BETWEEN 1 AND 512),\n    content_digest TEXT CHECK (content_digest IS NULL OR (length(content_digest) = 64 AND content_digest NOT GLOB '*[^0-9a-f]*')),\n    mime TEXT NOT NULL CHECK (length(mime) BETWEEN 1 AND 128),\n    kind TEXT NOT NULL CHECK (kind IN ('audio','video')),\n    title TEXT NOT NULL CHECK (length(title) BETWEEN 1 AND 512),\n    size INTEGER NOT NULL CHECK (size >= 0),\n    state TEXT NOT NULL CHECK (state IN ('ready','missing','changed','revoked')),\n    revision INTEGER NOT NULL CHECK (revision >= 1),\n    created_at TEXT NOT NULL,\n    updated_at TEXT NOT NULL,\n    CHECK ((scope_kind = 'user' AND scope_id = owner_subject_id) OR scope_kind = 'project')\n)",
	"table:media_audio_focus": "CREATE TABLE media_audio_focus (\n    singleton_id TEXT PRIMARY KEY CHECK (singleton_id = 'default'),\n    owner_subject_id TEXT NOT NULL DEFAULT '' CHECK (length(owner_subject_id) <= 128),\n    media_session_id TEXT CHECK (media_session_id IS NULL OR (length(media_session_id) = 26 AND substr(media_session_id, 1, 1) GLOB '[0-7]' AND media_session_id NOT GLOB '*[^0123456789ABCDEFGHJKMNPQRSTVWXYZ]*')),\n    playback_epoch INTEGER NOT NULL DEFAULT 0 CHECK (playback_epoch >= 0),\n    focus_token_digest TEXT NOT NULL DEFAULT '' CHECK (focus_token_digest = '' OR (length(focus_token_digest) = 64 AND focus_token_digest NOT GLOB '*[^0-9a-f]*')),\n    reason TEXT NOT NULL CHECK (reason IN ('none','owned_playback','external','tts')),\n    revision INTEGER NOT NULL CHECK (revision >= 1),\n    updated_at TEXT NOT NULL\n)",
	"table:media_bookmarks": "CREATE TABLE media_bookmarks (\n    owner_subject_id TEXT NOT NULL CHECK (length(owner_subject_id) BETWEEN 1 AND 128),\n    asset_id TEXT NOT NULL CHECK (length(asset_id) = 26 AND substr(asset_id, 1, 1) GLOB '[0-7]' AND asset_id NOT GLOB '*[^0123456789ABCDEFGHJKMNPQRSTVWXYZ]*'),\n    position_ms INTEGER NOT NULL CHECK (position_ms >= 0),\n    duration_ms INTEGER NOT NULL CHECK (duration_ms >= 0),\n    updated_at TEXT NOT NULL,\n    PRIMARY KEY (owner_subject_id, asset_id)\n)",
	"table:media_operations": "CREATE TABLE media_operations (\n    operation_id TEXT PRIMARY KEY CHECK (length(operation_id) = 26 AND substr(operation_id, 1, 1) GLOB '[0-7]' AND operation_id NOT GLOB '*[^0123456789ABCDEFGHJKMNPQRSTVWXYZ]*'),\n    media_session_id TEXT NOT NULL CHECK (length(media_session_id) = 26 AND substr(media_session_id, 1, 1) GLOB '[0-7]' AND media_session_id NOT GLOB '*[^0123456789ABCDEFGHJKMNPQRSTVWXYZ]*'),\n    parent_operation_id TEXT CHECK (parent_operation_id IS NULL OR (length(parent_operation_id) = 26 AND substr(parent_operation_id, 1, 1) GLOB '[0-7]' AND parent_operation_id NOT GLOB '*[^0123456789ABCDEFGHJKMNPQRSTVWXYZ]*')),\n    action TEXT NOT NULL CHECK (action IN ('play','pause','toggle','stop','previous','next','seek','set_volume','mute','unmute','create','move','remove','clear','jump')),\n    request_digest TEXT NOT NULL CHECK (length(request_digest) = 64 AND request_digest NOT GLOB '*[^0-9a-f]*'),\n    idempotency_key TEXT NOT NULL CHECK (length(idempotency_key) BETWEEN 1 AND 128),\n    phase TEXT NOT NULL CHECK (phase IN ('requested','awaiting_approval','dispatching','verifying','succeeded','uncertain','failed','cancelled')),\n    verification_status TEXT NOT NULL CHECK (verification_status IN ('not_applicable','not_started','pending','confirmed','unconfirmed')),\n    verification_source TEXT NOT NULL CHECK (verification_source IN ('none','process','window','uia','smtc','owned_runtime','artifact')),\n    error_code TEXT NOT NULL DEFAULT '' CHECK (length(error_code) <= 128),\n    evidence_json TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(evidence_json) AND length(evidence_json) <= 65536),\n    accepted_at TEXT,\n    dispatched_at TEXT,\n    completed_at TEXT,\n    revision INTEGER NOT NULL CHECK (revision >= 1),\n    created_at TEXT NOT NULL,\n    updated_at TEXT NOT NULL,\n    UNIQUE (media_session_id, idempotency_key),\n    UNIQUE (media_session_id, request_digest)\n)",
	"table:media_player_commands": "CREATE TABLE media_player_commands (\n    operation_id TEXT PRIMARY KEY CHECK (length(operation_id) = 26 AND substr(operation_id, 1, 1) GLOB '[0-7]' AND operation_id NOT GLOB '*[^0123456789ABCDEFGHJKMNPQRSTVWXYZ]*'),\n    media_session_id TEXT NOT NULL CHECK (length(media_session_id) = 26 AND substr(media_session_id, 1, 1) GLOB '[0-7]' AND media_session_id NOT GLOB '*[^0123456789ABCDEFGHJKMNPQRSTVWXYZ]*'),\n    lease_generation INTEGER NOT NULL CHECK (lease_generation >= 1),\n    asset_id TEXT CHECK (asset_id IS NULL OR (length(asset_id) = 26 AND substr(asset_id, 1, 1) GLOB '[0-7]' AND asset_id NOT GLOB '*[^0123456789ABCDEFGHJKMNPQRSTVWXYZ]*')),\n    playback_epoch INTEGER NOT NULL CHECK (playback_epoch >= 0),\n    desired_state_json TEXT NOT NULL CHECK (json_valid(desired_state_json) AND length(desired_state_json) <= 65536),\n    claimed_at TEXT,\n    acknowledged_at TEXT,\n    state TEXT NOT NULL CHECK (state IN ('pending','claimed','acknowledged','expired','cancelled','failed'))\n)",
	"table:media_player_leases": "CREATE TABLE media_player_leases (\n    media_session_id TEXT PRIMARY KEY CHECK (length(media_session_id) = 26 AND substr(media_session_id, 1, 1) GLOB '[0-7]' AND media_session_id NOT GLOB '*[^0123456789ABCDEFGHJKMNPQRSTVWXYZ]*'),\n    window_instance_id TEXT NOT NULL CHECK (length(window_instance_id) BETWEEN 1 AND 128),\n    navigation_epoch INTEGER NOT NULL CHECK (navigation_epoch >= 0),\n    lease_token_digest TEXT NOT NULL CHECK (length(lease_token_digest) = 64 AND lease_token_digest NOT GLOB '*[^0-9a-f]*'),\n    lease_expires_at TEXT NOT NULL,\n    generation INTEGER NOT NULL CHECK (generation >= 1)\n)",
	"table:media_queue_items": "CREATE TABLE media_queue_items (\n    item_id TEXT PRIMARY KEY CHECK (length(item_id) = 26 AND substr(item_id, 1, 1) GLOB '[0-7]' AND item_id NOT GLOB '*[^0123456789ABCDEFGHJKMNPQRSTVWXYZ]*'),\n    media_session_id TEXT NOT NULL CHECK (length(media_session_id) = 26 AND substr(media_session_id, 1, 1) GLOB '[0-7]' AND media_session_id NOT GLOB '*[^0123456789ABCDEFGHJKMNPQRSTVWXYZ]*'),\n    asset_id TEXT NOT NULL CHECK (length(asset_id) = 26 AND substr(asset_id, 1, 1) GLOB '[0-7]' AND asset_id NOT GLOB '*[^0123456789ABCDEFGHJKMNPQRSTVWXYZ]*'),\n    order_index INTEGER NOT NULL CHECK (order_index >= 0),\n    state TEXT NOT NULL CHECK (state IN ('queued','current','played','removed','failed')),\n    UNIQUE (media_session_id, order_index)\n)",
	"table:media_sessions": "CREATE TABLE media_sessions (\n    media_session_id TEXT PRIMARY KEY CHECK (length(media_session_id) = 26 AND substr(media_session_id, 1, 1) GLOB '[0-7]' AND media_session_id NOT GLOB '*[^0123456789ABCDEFGHJKMNPQRSTVWXYZ]*'),\n    owner_subject_id TEXT NOT NULL CHECK (length(owner_subject_id) BETWEEN 1 AND 128),\n    scope_kind TEXT NOT NULL CHECK (scope_kind IN ('user','project')),\n    scope_id TEXT NOT NULL CHECK (length(scope_id) BETWEEN 1 AND 128),\n    origin TEXT NOT NULL CHECK (origin IN ('owned','external')),\n    phase TEXT NOT NULL CHECK (phase IN ('idle','playing','paused','stalled','ended','uncertain','failed','stopped')),\n    verification_status TEXT NOT NULL CHECK (verification_status IN ('none','command_dispatched','verified_playing','verified_paused','verified_ended','verified_stopped')),\n    verification_source TEXT NOT NULL CHECK (verification_source IN ('none','smtc','owned_runtime')),\n    asset_id TEXT CHECK (asset_id IS NULL OR (length(asset_id) = 26 AND substr(asset_id, 1, 1) GLOB '[0-7]' AND asset_id NOT GLOB '*[^0123456789ABCDEFGHJKMNPQRSTVWXYZ]*')),\n    playback_epoch INTEGER NOT NULL DEFAULT 0 CHECK (playback_epoch >= 0),\n    auto_advance INTEGER NOT NULL DEFAULT 1 CHECK (auto_advance IN (0,1)),\n    position_ms INTEGER NOT NULL DEFAULT 0 CHECK (position_ms >= 0),\n    duration_ms INTEGER NOT NULL DEFAULT 0 CHECK (duration_ms >= 0),\n    volume INTEGER NOT NULL DEFAULT 100 CHECK (volume >= 0 AND volume <= 100),\n    muted INTEGER NOT NULL DEFAULT 0 CHECK (muted IN (0,1)),\n    external_app_key TEXT NOT NULL DEFAULT '' CHECK (length(external_app_key) <= 128),\n    external_session_key TEXT NOT NULL DEFAULT '' CHECK (length(external_session_key) <= 128),\n    queue_revision INTEGER NOT NULL DEFAULT 1 CHECK (queue_revision >= 1),\n    revision INTEGER NOT NULL CHECK (revision >= 1),\n    created_at TEXT NOT NULL,\n    updated_at TEXT NOT NULL,\n    CHECK ((scope_kind = 'user' AND scope_id = owner_subject_id) OR scope_kind = 'project')\n)",
	"table:media_settings": "CREATE TABLE media_settings (\n    singleton_id TEXT PRIMARY KEY CHECK (singleton_id = 'default'),\n    media_session_v2 INTEGER NOT NULL DEFAULT 0 CHECK (media_session_v2 IN (0,1)),\n    activity_center_v2 INTEGER NOT NULL DEFAULT 0 CHECK (activity_center_v2 IN (0,1)),\n    auto_advance INTEGER NOT NULL DEFAULT 1 CHECK (auto_advance IN (0,1)),\n    revision INTEGER NOT NULL CHECK (revision >= 1),\n    updated_at TEXT NOT NULL\n)",
	"table:ocr_artifact_leases": "CREATE TABLE ocr_artifact_leases (\n    lease_id TEXT PRIMARY KEY CHECK (length(lease_id) = 26 AND substr(lease_id, 1, 1) GLOB '[0-7]' AND lease_id NOT GLOB '*[^0123456789ABCDEFGHJKMNPQRSTVWXYZ]*'),\n    artifact_id TEXT NOT NULL REFERENCES ocr_artifacts(artifact_id),\n    owner TEXT NOT NULL CHECK (length(owner) BETWEEN 1 AND 128),\n    expires_at TEXT NOT NULL\n)",
	"table:ocr_artifacts": "CREATE TABLE ocr_artifacts (\n    artifact_id TEXT PRIMARY KEY CHECK (length(artifact_id) = 26 AND substr(artifact_id, 1, 1) GLOB '[0-7]' AND artifact_id NOT GLOB '*[^0123456789ABCDEFGHJKMNPQRSTVWXYZ]*'),\n    owner_subject_id TEXT NOT NULL CHECK (length(owner_subject_id) BETWEEN 1 AND 128),\n    scope_kind TEXT NOT NULL CHECK (scope_kind IN ('user','project')),\n    scope_id TEXT NOT NULL CHECK (length(scope_id) BETWEEN 1 AND 128),\n    run_id TEXT NOT NULL CHECK (length(run_id) = 26 AND substr(run_id, 1, 1) GLOB '[0-7]' AND run_id NOT GLOB '*[^0123456789ABCDEFGHJKMNPQRSTVWXYZ]*'),\n    cas_ref TEXT NOT NULL CHECK (length(cas_ref) BETWEEN 1 AND 512),\n    sha256 TEXT NOT NULL CHECK (length(sha256) = 64 AND sha256 NOT GLOB '*[^0-9a-f]*'),\n    size INTEGER NOT NULL CHECK (size >= 0),\n    mime TEXT NOT NULL CHECK (length(mime) BETWEEN 1 AND 128),\n    expires_at TEXT NOT NULL,\n    created_at TEXT NOT NULL,\n    CHECK ((scope_kind = 'user' AND scope_id = owner_subject_id) OR scope_kind = 'project')\n)",
	"table:ocr_document_runs": "CREATE TABLE ocr_document_runs (\n    run_id TEXT PRIMARY KEY CHECK (length(run_id) = 26 AND substr(run_id, 1, 1) GLOB '[0-7]' AND run_id NOT GLOB '*[^0123456789ABCDEFGHJKMNPQRSTVWXYZ]*'),\n    request_id TEXT NOT NULL UNIQUE CHECK (length(request_id) BETWEEN 1 AND 128),\n    owner_subject_id TEXT NOT NULL CHECK (length(owner_subject_id) BETWEEN 1 AND 128),\n    scope_kind TEXT NOT NULL CHECK (scope_kind IN ('user','project')),\n    scope_id TEXT NOT NULL CHECK (length(scope_id) BETWEEN 1 AND 128),\n    document_digest TEXT NOT NULL CHECK (length(document_digest) = 64 AND document_digest NOT GLOB '*[^0-9a-f]*'),\n    policy_json TEXT NOT NULL CHECK (json_valid(policy_json) AND length(policy_json) <= 65536),\n    gate_json TEXT NOT NULL CHECK (json_valid(gate_json) AND length(gate_json) <= 65536),\n    mode TEXT NOT NULL CHECK (length(mode) BETWEEN 1 AND 64),\n    provider_id TEXT NOT NULL DEFAULT '' CHECK (length(provider_id) <= 128),\n    model_id TEXT NOT NULL DEFAULT '' CHECK (length(model_id) <= 128),\n    pack_manifest_digest TEXT CHECK (pack_manifest_digest IS NULL OR (length(pack_manifest_digest) = 64 AND pack_manifest_digest NOT GLOB '*[^0-9a-f]*')),\n    runtime_profile_digest TEXT CHECK (runtime_profile_digest IS NULL OR (length(runtime_profile_digest) = 64 AND runtime_profile_digest NOT GLOB '*[^0-9a-f]*')),\n    pipeline_kind TEXT NOT NULL DEFAULT '' CHECK (length(pipeline_kind) <= 64),\n    allow_remote INTEGER NOT NULL DEFAULT 0 CHECK (allow_remote = 0),\n    credential_ref TEXT NOT NULL DEFAULT '' CHECK (credential_ref = ''),\n    request_snapshot_digest TEXT NOT NULL CHECK (length(request_snapshot_digest) = 64 AND request_snapshot_digest NOT GLOB '*[^0-9a-f]*'),\n    state TEXT NOT NULL CHECK (state IN ('queued','running','succeeded','failed','cancelled')),\n    page_count INTEGER NOT NULL DEFAULT 0 CHECK (page_count >= 0),\n    actual_engine TEXT NOT NULL DEFAULT '' CHECK (length(actual_engine) <= 128),\n    created_at TEXT NOT NULL,\n    updated_at TEXT NOT NULL,\n    UNIQUE (run_id, request_snapshot_digest),\n    CHECK ((scope_kind = 'user' AND scope_id = owner_subject_id) OR scope_kind = 'project')\n)",
	"table:ocr_legacy_registrations": "CREATE TABLE ocr_legacy_registrations (\n    registration_id TEXT PRIMARY KEY CHECK (length(registration_id) = 26 AND substr(registration_id, 1, 1) GLOB '[0-7]' AND registration_id NOT GLOB '*[^0123456789ABCDEFGHJKMNPQRSTVWXYZ]*'),\n    owner_subject_id TEXT NOT NULL CHECK (length(owner_subject_id) BETWEEN 1 AND 128),\n    scope_kind TEXT NOT NULL CHECK (scope_kind IN ('user','project')),\n    scope_id TEXT NOT NULL CHECK (length(scope_id) BETWEEN 1 AND 128),\n    engine_id TEXT NOT NULL CHECK (engine_id = 'ppocr'),\n    root_ref TEXT NOT NULL CHECK (length(root_ref) BETWEEN 1 AND 512),\n    marker_detected INTEGER NOT NULL DEFAULT 0 CHECK (marker_detected IN (0,1)),\n    state TEXT NOT NULL CHECK (state = 'registered_unwired'),\n    available INTEGER NOT NULL DEFAULT 0 CHECK (available = 0),\n    imported_at TEXT NOT NULL,\n    revision INTEGER NOT NULL CHECK (revision >= 1),\n    UNIQUE (owner_subject_id, scope_kind, scope_id, engine_id),\n    CHECK ((scope_kind = 'user' AND scope_id = owner_subject_id) OR scope_kind = 'project')\n)",
	"table:ocr_pack_gates": "CREATE TABLE ocr_pack_gates (\n    pack_id TEXT PRIMARY KEY CHECK (length(pack_id) BETWEEN 1 AND 64),\n    install_enabled INTEGER NOT NULL DEFAULT 0 CHECK (install_enabled IN (0,1)),\n    auto_route_enabled INTEGER NOT NULL DEFAULT 0 CHECK (auto_route_enabled IN (0,1)),\n    verified_runtime_profile_digest TEXT CHECK (verified_runtime_profile_digest IS NULL OR (length(verified_runtime_profile_digest) = 64 AND verified_runtime_profile_digest NOT GLOB '*[^0-9a-f]*')),\n    disabled_reason TEXT NOT NULL DEFAULT 'NO_VERIFIED_RUNTIME_PROFILE' CHECK (length(disabled_reason) BETWEEN 1 AND 128),\n    revision INTEGER NOT NULL CHECK (revision >= 1),\n    updated_at TEXT NOT NULL\n)",
	"table:ocr_pack_notices": "CREATE TABLE ocr_pack_notices (\n    pack_id TEXT NOT NULL CHECK (length(pack_id) BETWEEN 1 AND 64),\n    manifest_digest TEXT NOT NULL CHECK (length(manifest_digest) = 64 AND manifest_digest NOT GLOB '*[^0-9a-f]*'),\n    version TEXT NOT NULL CHECK (length(version) BETWEEN 1 AND 64),\n    notice_digest TEXT NOT NULL CHECK (length(notice_digest) = 64 AND notice_digest NOT GLOB '*[^0-9a-f]*'),\n    notice_bytes BLOB NOT NULL,\n    notice_ref TEXT NOT NULL CHECK (length(notice_ref) BETWEEN 1 AND 512),\n    verified_at TEXT NOT NULL,\n    installed_at TEXT,\n    uninstalled_at TEXT,\n    PRIMARY KEY (pack_id, manifest_digest)\n)",
	"table:ocr_pack_operations": "CREATE TABLE ocr_pack_operations (\n    operation_id TEXT PRIMARY KEY CHECK (length(operation_id) = 26 AND substr(operation_id, 1, 1) GLOB '[0-7]' AND operation_id NOT GLOB '*[^0123456789ABCDEFGHJKMNPQRSTVWXYZ]*'),\n    pack_id TEXT NOT NULL CHECK (length(pack_id) BETWEEN 1 AND 64),\n    subject_id TEXT NOT NULL CHECK (length(subject_id) BETWEEN 1 AND 128),\n    action TEXT NOT NULL CHECK (action IN ('install','uninstall')),\n    idempotency_key TEXT NOT NULL CHECK (length(idempotency_key) BETWEEN 1 AND 128),\n    request_digest TEXT NOT NULL CHECK (length(request_digest) = 64 AND request_digest NOT GLOB '*[^0-9a-f]*'),\n    catalog_revision TEXT NOT NULL DEFAULT '' CHECK (length(catalog_revision) <= 128),\n    accepted_manifest_digest TEXT CHECK (accepted_manifest_digest IS NULL OR (length(accepted_manifest_digest) = 64 AND accepted_manifest_digest NOT GLOB '*[^0-9a-f]*')),\n    phase TEXT NOT NULL CHECK (phase IN ('requested','preflighting','downloading','verifying','installing','self_testing','succeeded','failed','cancelled')),\n    progress INTEGER NOT NULL DEFAULT 0 CHECK (progress >= 0 AND progress <= 100),\n    cancel_requested INTEGER NOT NULL DEFAULT 0 CHECK (cancel_requested IN (0,1)),\n    result_json TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(result_json) AND length(result_json) <= 65536),\n    error_code TEXT NOT NULL DEFAULT '' CHECK (length(error_code) <= 128),\n    lease_owner TEXT CHECK (lease_owner IS NULL OR length(lease_owner) BETWEEN 1 AND 128),\n    lease_until TEXT,\n    heartbeat_at TEXT,\n    attempt INTEGER NOT NULL DEFAULT 0 CHECK (attempt >= 0),\n    fence INTEGER NOT NULL DEFAULT 0 CHECK (fence >= 0),\n    revision INTEGER NOT NULL CHECK (revision >= 1),\n    created_at TEXT NOT NULL,\n    updated_at TEXT NOT NULL,\n    UNIQUE (pack_id, idempotency_key),\n    UNIQUE (pack_id, request_digest)\n)",
	"table:ocr_pack_state": "CREATE TABLE ocr_pack_state (\n    pack_id TEXT PRIMARY KEY CHECK (length(pack_id) BETWEEN 1 AND 64),\n    availability TEXT NOT NULL CHECK (availability IN ('not_installed','ready','quarantined')),\n    current_version TEXT CHECK (current_version IS NULL OR length(current_version) BETWEEN 1 AND 64),\n    previous_version TEXT CHECK (previous_version IS NULL OR length(previous_version) BETWEEN 1 AND 64),\n    active_operation_id TEXT CHECK (active_operation_id IS NULL OR (length(active_operation_id) = 26 AND substr(active_operation_id, 1, 1) GLOB '[0-7]' AND active_operation_id NOT GLOB '*[^0123456789ABCDEFGHJKMNPQRSTVWXYZ]*')),\n    last_health_at TEXT,\n    last_error_code TEXT NOT NULL DEFAULT '' CHECK (length(last_error_code) <= 128),\n    revision INTEGER NOT NULL CHECK (revision >= 1),\n    updated_at TEXT NOT NULL\n)",
	"table:ocr_pack_versions": "CREATE TABLE ocr_pack_versions (\n    pack_id TEXT NOT NULL CHECK (length(pack_id) BETWEEN 1 AND 64),\n    version TEXT NOT NULL CHECK (length(version) BETWEEN 1 AND 64),\n    manifest_digest TEXT NOT NULL CHECK (length(manifest_digest) = 64 AND manifest_digest NOT GLOB '*[^0-9a-f]*'),\n    install_root_ref TEXT NOT NULL CHECK (length(install_root_ref) BETWEEN 1 AND 512),\n    engine_version TEXT NOT NULL DEFAULT '' CHECK (length(engine_version) <= 128),\n    device_kind TEXT CHECK (device_kind IS NULL OR device_kind IN ('cpu','gpu')),\n    state TEXT NOT NULL CHECK (state IN ('verified','quarantined')),\n    created_at TEXT NOT NULL,\n    PRIMARY KEY (pack_id, version)\n)",
	"table:ocr_page_results": "CREATE TABLE ocr_page_results (\n    run_id TEXT NOT NULL CHECK (length(run_id) = 26 AND substr(run_id, 1, 1) GLOB '[0-7]' AND run_id NOT GLOB '*[^0123456789ABCDEFGHJKMNPQRSTVWXYZ]*'),\n    page INTEGER NOT NULL CHECK (page >= 1),\n    request_snapshot_digest TEXT NOT NULL CHECK (length(request_snapshot_digest) = 64 AND request_snapshot_digest NOT GLOB '*[^0-9a-f]*'),\n    actual_engine TEXT NOT NULL CHECK (length(actual_engine) BETWEEN 1 AND 128),\n    engine_version TEXT NOT NULL DEFAULT '' CHECK (length(engine_version) <= 128),\n    pack_version TEXT NOT NULL DEFAULT '' CHECK (length(pack_version) <= 64),\n    pipeline_kind TEXT NOT NULL DEFAULT '' CHECK (length(pipeline_kind) <= 64),\n    source_digest TEXT NOT NULL CHECK (length(source_digest) = 64 AND source_digest NOT GLOB '*[^0-9a-f]*'),\n    complete INTEGER NOT NULL CHECK (complete IN (0,1)),\n    uncertain INTEGER NOT NULL CHECK (uncertain IN (0,1)),\n    layout_json TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(layout_json) AND length(layout_json) <= 65536),\n    text_ref TEXT NOT NULL DEFAULT '' CHECK (length(text_ref) <= 512),\n    warnings_json TEXT NOT NULL DEFAULT '[]' CHECK (json_valid(warnings_json) AND length(warnings_json) <= 8192),\n    PRIMARY KEY (run_id, page),\n    FOREIGN KEY (run_id, request_snapshot_digest) REFERENCES ocr_document_runs(run_id, request_snapshot_digest)\n)",
	"table:ocr_settings": "CREATE TABLE ocr_settings (\n    owner_subject_id TEXT NOT NULL CHECK (length(owner_subject_id) BETWEEN 1 AND 128),\n    scope_kind TEXT NOT NULL CHECK (scope_kind IN ('user','project')),\n    scope_id TEXT NOT NULL CHECK (length(scope_id) BETWEEN 1 AND 128),\n    policy_json TEXT NOT NULL CHECK (json_valid(policy_json) AND length(policy_json) <= 65536),\n    policy_revision TEXT NOT NULL CHECK (length(policy_revision) = 64 AND policy_revision NOT GLOB '*[^0-9a-f]*'),\n    revision INTEGER NOT NULL CHECK (revision >= 1),\n    legacy_imported_at TEXT,\n    created_at TEXT NOT NULL,\n    updated_at TEXT NOT NULL,\n    PRIMARY KEY (owner_subject_id, scope_kind, scope_id),\n    CHECK ((scope_kind = 'user' AND scope_id = owner_subject_id) OR scope_kind = 'project')\n)",
	"table:ocr_version_leases": "CREATE TABLE ocr_version_leases (\n    lease_id TEXT PRIMARY KEY CHECK (length(lease_id) = 26 AND substr(lease_id, 1, 1) GLOB '[0-7]' AND lease_id NOT GLOB '*[^0123456789ABCDEFGHJKMNPQRSTVWXYZ]*'),\n    pack_id TEXT NOT NULL CHECK (length(pack_id) BETWEEN 1 AND 64),\n    version TEXT NOT NULL CHECK (length(version) BETWEEN 1 AND 64),\n    run_id TEXT CHECK (run_id IS NULL OR (length(run_id) = 26 AND substr(run_id, 1, 1) GLOB '[0-7]' AND run_id NOT GLOB '*[^0123456789ABCDEFGHJKMNPQRSTVWXYZ]*')),\n    owner TEXT NOT NULL CHECK (length(owner) BETWEEN 1 AND 128),\n    fence INTEGER NOT NULL DEFAULT 0 CHECK (fence >= 0),\n    expires_at TEXT NOT NULL\n)",
}
